import sys

def main():
    import sys
    import collections
    import heapq

    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    degree = [0] * (n + 1)
    parent = [0] * (n + 1)
    children = collections.defaultdict(list)

    for u in a:
        degree[u] += 1

    q = []
    for i in range(1, n + 1):
        if degree[i] == 0:
            heapq.heappush(q, (2 ** i, i))

    root = None
    for u in a:
        if degree[u] > 1:
            root = u
            break

    if root is None:
        root = a[-1]

    for u in a:
        if degree[u] == 0:
            v = u
            while parent[v] == 0:
                parent[v] = u
                v = root
            degree[parent[v]] -= 1
            children[u].append(parent[v])
            if degree[parent[v]] == 0:
                heapq.heappush(q, (2 ** parent[v], parent[v]))

    if len(children[root]) < n - 1:
        print(-1)
        return

    print(root)
    edges = set()
    def dfs(u):
        for v in children[u]:
            if (u, v) not in edges and (v, u) not in edges:
                edges.add((u, v))
                print(u, v)
                dfs(v)

    dfs(root)

main()
